local CombMaker = {}
local PRODUCTS = {
    wooden_comb = { name = "Leseni glavnik", woodCost = 1, time = 1, cost = 5, happiness = 1, description = "Preprost glavnik." },
    bone_comb = { name = "Kosten glavnik", boneCost = 1, time = 2, cost = 15, happiness = 2, description = "Fini glavnik iz kosti." },
    ivory_comb = { name = "Slonokoščeni glavnik", ivoryCost = 1, time = 5, cost = 80, happiness = 5, prestige = 5, description = "Luksuzni glavnik." },
    hair_pin = { name = "Lasnica", metalCost = 1, time = 1, cost = 10, happiness = 1, description = "Kovinska lasnica." },
    jeweled_comb = { name = "Draguljarni glavnik", ivoryCost = 1, jewelCost = 1, goldCost = 1, time = 10, cost = 300, happiness = 8, prestige = 15, description = "Glavnik z drago kamen." },
    royal_hairpiece = { name = "Kraljevski lasnik", goldCost = 2, jewelCost = 2, silkCost = 1, time = 14, cost = 500, happiness = 12, prestige = 25, description = "Kraljevski lasni nakit." },
}
local BUILDINGS = {
    workshop = { name = "Glavničarska delavnica", cost = { gold = 150, wood = 50 }, upkeep = 3, qualityBonus = 5 },
    bone_shop = { name = "Kostarska delavnica", cost = { gold = 400, wood = 100, stone = 50 }, upkeep = 10, qualityBonus = 10 },
    jewel_workshop = { name = "Nakitarska delavnica", cost = { gold = 1000, wood = 200, stone = 200, iron = 50 }, upkeep = 25, qualityBonus = 20 },
    royal_combiner = { name = "Kraljevski glavničar", cost = { gold = 3000, wood = 400, stone = 600, gold = 50 }, upkeep = 60, qualityBonus = 35, prestigeBonus = 15 },
}
CombMaker.woodStock = 15; CombMaker.boneStock = 5; CombMaker.ivoryStock = 3; CombMaker.metalStock = 8; CombMaker.jewelStock = 2; CombMaker.goldStock = 3; CombMaker.silkStock = 2
CombMaker.productStock = {}; CombMaker.buildings = {}; CombMaker.maker = nil; CombMaker.activeMaking = {}; CombMaker.totalProducts = 0; CombMaker.dayTimer = 0
function CombMaker.init() CombMaker.woodStock=15; CombMaker.boneStock=5; CombMaker.ivoryStock=3; CombMaker.metalStock=8; CombMaker.jewelStock=2; CombMaker.goldStock=3; CombMaker.silkStock=2; CombMaker.productStock={}; CombMaker.buildings={}; CombMaker.maker=nil; CombMaker.activeMaking={}; CombMaker.totalProducts=0; CombMaker.dayTimer=0; print("[CombMaker] Royal Comb & Hair Accessory Maker System initialized (6 products, 4 buildings)") end
function CombMaker.hireMaker(n,s) s=s or math.random(35,80); local c=200+s*4; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; CombMaker.maker={name=n or ("Glavničar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Glavničar najet: %s (spretnost: %d)",CombMaker.maker.name,s),"success") end; return true end
function CombMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function CombMaker.build(id) local ok,e=CombMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(CombMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function CombMaker.getQualityBonus() local b=0; for _,bd in ipairs(CombMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function CombMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and CombMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.boneCost and CombMaker.boneStock<(d.boneCost or 0) then return false,"Premalo kosti" end; if d.ivoryCost and CombMaker.ivoryStock<(d.ivoryCost or 0) then return false,"Premalo slonovine" end; if d.metalCost and CombMaker.metalStock<(d.metalCost or 0) then return false,"Premalo kovine" end; if d.jewelCost and CombMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo dragih kamnov" end; if d.goldCost and CombMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.silkCost and CombMaker.silkStock<(d.silkCost or 0) then return false,"Premalo svile" end; if #CombMaker.buildings==0 then return false,"Potrebna delavnica" end; if not CombMaker.maker then return false,"Potreben glavničar" end; return true end
function CombMaker.make(pt) local ok,e=CombMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then CombMaker.woodStock=CombMaker.woodStock-d.woodCost end; if d.boneCost then CombMaker.boneStock=CombMaker.boneStock-d.boneCost end; if d.ivoryCost then CombMaker.ivoryStock=CombMaker.ivoryStock-d.ivoryCost end; if d.metalCost then CombMaker.metalStock=CombMaker.metalStock-d.metalCost end; if d.jewelCost then CombMaker.jewelStock=CombMaker.jewelStock-d.jewelCost end; if d.goldCost then CombMaker.goldStock=CombMaker.goldStock-d.goldCost end; if d.silkCost then CombMaker.silkStock=CombMaker.silkStock-d.silkCost end; local t=d.time; if CombMaker.maker then t=math.max(1,t-math.floor(CombMaker.maker.skill/15)) end; table.insert(CombMaker.activeMaking,{id="comb_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost,happiness=d.happiness or 0,prestige=d.prestige or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %s (%d dni)",d.name,t),"info") end; return true end
function CombMaker.completeMaking(m) local q=1.0+(CombMaker.getQualityBonus()/100); if CombMaker.maker then q=q+(CombMaker.maker.skill/200) end; q=math.min(2.0,q); CombMaker.productStock[m.productType]=(CombMaker.productStock[m.productType] or 0)+1; CombMaker.totalProducts=CombMaker.totalProducts+1; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness*q) end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if CombMaker.maker then CombMaker.maker.itemsMade=CombMaker.maker.itemsMade+1; if math.random()<0.15 then CombMaker.maker.skill=math.min(100,CombMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Glavnik izdelan: %s (kakovost: %.1f)",m.productName,q),"success") end end
function CombMaker.update(dt) if not _G.state then return end; CombMaker.dayTimer=CombMaker.dayTimer+dt; if CombMaker.dayTimer>=30 then CombMaker.dayTimer=0; for i=#CombMaker.activeMaking,1,-1 do local m=CombMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then CombMaker.completeMaking(m); table.remove(CombMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(CombMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if CombMaker.maker then tu=tu+5 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function CombMaker.getStats() return {woodStock=CombMaker.woodStock,boneStock=CombMaker.boneStock,ivoryStock=CombMaker.ivoryStock,jewelStock=CombMaker.jewelStock,productStock=CombMaker.productStock,numBuildings=#CombMaker.buildings,hasMaker=CombMaker.maker~=nil,makerName=CombMaker.maker and CombMaker.maker.name or "—",makerSkill=CombMaker.maker and CombMaker.maker.skill or 0,activeMaking=#CombMaker.activeMaking,totalProducts=CombMaker.totalProducts} end
return CombMaker
